// One returns a single titulo record from the query.
func (q tituloQuery) One(ctx context.Context, exec boil.ContextExecutor) (*Titulo, error) {
	o := &Titulo{}

	queries.SetLimit(q.Query, 1)

	err := q.Bind(ctx, exec, o)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "models: failed to execute a one query for titulos")
	}

	if err := o.doAfterSelectHooks(ctx, exec); err != nil {
		return o, err
	}

	return o, nil
}

// All returns all Titulo records from the query.
func (q tituloQuery) All(ctx context.Context, exec boil.ContextExecutor) (TituloSlice, error) {
	var o []*Titulo

	err := q.Bind(ctx, exec, &o)
	if err != nil {
		return nil, errors.Wrap(err, "models: failed to assign all query results to Titulo slice")
	}

	if len(tituloAfterSelectHooks) != 0 {
		for _, obj := range o {
			if err := obj.doAfterSelectHooks(ctx, exec); err != nil {
				return o, err
			}
		}
	}

	return o, nil
}

