// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *Titulo) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindTitulo(ctx, exec, o.TitID)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *TituloSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := TituloSlice{}
	var args []interface{}
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), tituloPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT `titulos`.* FROM `titulos` WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 0, tituloPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "models: unable to reload all in TituloSlice")
	}

	*o = slice

	return nil
}

